edges = [(0,1),(1,2),(2,3),(3,4),(4,6),(6,8),(8,9),(9,10),(10,11),(5,7)]
from collections import defaultdict
deg = defaultdict(int)
for u,v in edges:
    deg[u]+=1; deg[v]+=1
print("vertices covered:", sorted(deg.keys()))
print("degrees:", dict(deg))
print("num edges:", len(edges))
print("min/max deg:", min(deg.values()), max(deg.values()))
# bipartite check via BFS
adj = defaultdict(list)
for u,v in edges:
    adj[u].append(v); adj[v].append(u)
color = {}
for s in range(12):
    if s not in color:
        color[s]=0
        stack=[s]
        while stack:
            x=stack.pop()
            for y in adj[x]:
                if y not in color:
                    color[y]=1-color[x]; stack.append(y)
                elif color[y]==color[x]:
                    print("NOT BIPARTITE"); break
print("bipartite OK")
print("(5,7) in:", (5,7) in edges, " (4,6) in:", (4,6) in edges)
